/** One ticket history row split for a table: verb, `Oct 23`, `00:55`, and `auto`/`manual` (none when it lapsed). */
export function ticketUseParts(use: { at: number; result: string; source: string }): {
	verb: string;
	day: string;
	clock: string;
	source: string | null;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", hourCycle: "h23" }),
		source: use.result === "expired" ? null : use.source,
	};
}

/** One ticket history row: `Used Oct 23 00:55 · auto`. */
export function ticketUseLabel(use: { at: number; result: string; source: string }): string {
	const { verb, day, clock, source } = ticketUseParts(use);
	return source ? `${verb} ${day} ${clock} · ${source}` : `${verb} ${day} ${clock}`;
}

edits.newText:
/** The kind of reset a ticket is: its model name for a model reset, else `Full`. */
export function ticketKind(ticket: { scope?: string; model?: string }): string {
	return ticket.scope === "model" && ticket.model ? ticket.model : "Full";
}

/** The name a ticket is shown under: `Fable reset` or `Full reset`. */
export function ticketName(ticket: { scope?: string; model?: string }): string {
	return `${ticketKind(ticket)} reset`;
}

/** What spending a ticket clears, in the card's own words. */
export function ticketEffect(ticket: { scope?: string; model?: string }): string {
	if (ticket.scope === "model" && ticket.model) {
		return `Resets the ${ticket.model} allowance only; weekly usage is untouched.`;
	}
	return "Resets weekly usage now, not the monthly cap.";
}

type ResetTicketLike = { id: string; expiresAt: number; scope?: string; model?: string };

/** Tickets still spendable at `now`, soonest expiry first. */
export function liveTickets<T extends ResetTicketLike>(tickets: readonly T[], now = Date.now()): T[] {
	return tickets
		.filter((ticket) => {
			const ms = resetAtMs(ticket.expiresAt);
			return ms != null && ms > now;
		})
		.sort((a, b) => (resetAtMs(a.expiresAt) ?? 0) - (resetAtMs(b.expiresAt) ?? 0));
}

/** The soonest live ticket that clears the weekly window, or nothing when only model resets are left. */
export function weeklyTicket<T extends ResetTicketLike>(tickets: readonly T[], now = Date.now()): T | undefined {
	return liveTickets(tickets, now).find((ticket) => ticket.scope !== "model");
}

/** One ticket history row split for a table: verb, `Oct 23`, `00:55`, the reset kind, and `auto`/`manual` (none when it lapsed). */
export function ticketUseParts(use: {
	at: number;
	result: string;
	source: string;
	scope?: string;
	model?: string;
}): {
	verb: string;
	day: string;
	clock: string;
	kind: string;
	source: string | null;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", hourCycle: "h23" }),
		kind: ticketKind(use),
		source: use.result === "expired" ? null : use.source,
	};
}

/** One ticket history row: `Used Oct 23 00:55 · Full reset · auto`. */
export function ticketUseLabel(use: {
	at: number;
	result: string;
	source: string;
	scope?: string;
	model?: string;
}): string {
	const { verb, day, clock, kind, source } = ticketUseParts(use);
	const row = `${verb} ${day} ${clock} · ${kind} reset`;
	return source ? `${row} · ${source}` : row;
}

